'use strict';
// Keep result reading simple and describe the two theme stages in audit language.
const thBase={ewHeader,awToolbar,workbench,configPanel,twPreview,awPromptModal,modalContent,awRows,awProgress,awOutputRows,awDoExport,handleAction,awReviewHTML,tcOutput,trDownloadPage};
const TH_DEFAULTS={extract:'逐份摘录资料涉及的主要事项、相关单位、金额及单位、日期和原文依据。保留事项之间的关系；资料未说明的内容标注“未提取到”，不得补写。',summarize:'依据已摘录的资料要点，将同类事项归在同一主题下；概括共同内容，列出不同资料之间的差异和需继续核对的事项。每个主题标明来源资料，不作超出资料的判断。'};
const thOldDefaults=Object.fromEntries(['extract','summarize'].map(key=>[key,awDefaults.theme[key].content]));
for(const key of ['extract','summarize'])awDefaults.theme[key].content=TH_DEFAULTS[key];
function thPrepareDefaults(c){for(const key of ['extract','summarize']){const stage=c.stages[key],old=thOldDefaults[key],generic='请依据所选资料，'+tool('theme').desc+'。保留原文引用；未提取到的内容如实标注，不补充资料外事实。';if(!stage.customized&&stage.origin!=='personal'&&[old,...(key==='extract'?[generic]:[])].includes(stage.content))stage.content=TH_DEFAULTS[key];}}
TW_META.theme=['添加资料','设置主题归纳提示词','分别选择资料要点和主题归纳提示词。'];
TR_OUTPUTS.theme=['主题汇总与资料要点','汇总同类事项，保留逐份资料要点与原文来源。'];
trDownloadPage=function(task){const html=thBase.trDownloadPage(task);return task.toolId==='theme'?html.replace('当前可下载基础信息，主题归纳尚未完成。','主题汇总尚未完成，可先导出资料要点。'):html;};
PROMPT_STAGES.theme.forEach(s=>s[1]=s[0]==='extract'?'提取资料要点':'汇总同类事项');
function thResultHeader(html,selector,task){if(!task||task.status==='running')return html;const root=document.createElement('div');root.innerHTML=html;root.querySelectorAll(selector+' [data-action]:not([data-action="export"])').forEach(n=>n.remove());root.querySelector('.ew-steps,.aw-steps')?.remove();const exp=root.querySelector('[data-action=export]');if(exp){exp.textContent='导出';exp.title='导出本次结果';}if(task.toolId==='theme'&&task.summaryGenerating){const status=root.querySelector('.tag');if(status)status.outerHTML=tag('正在汇总','blue');}return root.innerHTML;}
ewHeader=function(task){return thResultHeader(thBase.ewHeader(task),'.ew-command-actions',task);};
awToolbar=function(task){let html=thBase.awToolbar(task);if(task&&['word','theme'].includes(task.toolId))return thResultHeader(html,'.aw-command-actions',task);if(state.toolId==='theme'&&!task){const root=document.createElement('div');root.innerHTML=html;const run=root.querySelector('[data-action=run]');if(run)run.textContent='开始归纳';return root.innerHTML;}return html;};
workbench=function(){const t=currentTask(),readOnlyResult=t&&['extract','word','theme'].includes(state.toolId)&&!trMode();if(readOnlyResult&&t.status!=='running'){configExpanded=false;if(state.toolId==='extract')efView.panel='preview';}const html=thBase.workbench();if(!readOnlyResult){if(state.toolId==='theme'&&!t){const root=document.createElement('div');root.innerHTML=html;const run=root.querySelector('[data-action=run]');if(run)run.textContent='开始归纳';if(!twDocs().length)root.querySelector('.tw-empty-small')?.remove();return root.innerHTML;}return html;}const root=document.createElement('div');root.innerHTML=html;if(state.toolId==='extract')root.querySelector('.ef-mobile-tabs')?.remove();root.firstElementChild?.classList.add('th-reading-result');return root.innerHTML;};
function thStageCard(c,key,locked){const stage=c.stages[key],extract=key==='extract',label=extract?'资料要点':'归纳要求',help=extract?'每份资料需要摘录哪些内容？':'按什么主题汇总，需要对照哪些内容？';return '<section class="th-rule"><div><h3>'+label+'</h3>'+A(locked?'查看':'调整','aw-prompt','data-stage="'+key+'"')+'</div><p>'+help+'</p><p class="th-rule-content" title="'+E(stage.content)+'">'+E(stage.content)+'</p></section>';}
configPanel=function(){const html=thBase.configPanel();if(state.toolId!=='theme')return html;const root=document.createElement('div');root.innerHTML=html;const panel=root.querySelector('aside'),task=currentTask(),locked=!!task,c=awConfig();if(!panel)return html;if(!locked)thPrepareDefaults(c);panel.classList.add('th-config');const head=panel.querySelector('.ew-panel-head h2');if(head)head.innerHTML=(locked?'':'<span class="tw-step">Step 3</span>')+(locked?'执行时的归纳要求':'设置主题归纳提示词');panel.setAttribute('aria-label',locked?'执行时的归纳要求':'Step 3 设置主题归纳提示词');panel.querySelector('.ew-config-body').innerHTML='<p class="th-config-intro">'+(locked?'本次执行时使用的要求，只读查看。':'分别选择资料要点和主题归纳提示词。')+'</p><section class="th-scheme"><label for="th-scheme">使用方案</label><select id="th-scheme" data-config="template" aria-label="选择归纳方案" '+(locked?'disabled':'')+'>'+options([...new Set([tool('theme').template,...state.templates.filter(t=>t.toolId==='theme'&&!t.stage).map(t=>t.name),c.template])],c.template)+'</select></section>'+thStageCard(c,'extract',locked)+thStageCard(c,'summarize',locked)+(!locked?'<details class="th-scheme-management"><summary>方案管理</summary><div>'+B('另存为个人方案','aw-save-scheme','sm')+B('导入方案','aw-import-config','ghost sm')+B('导出方案','v2-export-config','ghost sm')+'</div></details><p class="th-auto-note">点击“开始归纳”，自动完成资料摘录和主题汇总。</p>':'');return root.innerHTML;};
twPreview=function(){const html=thBase.twPreview();if(state.toolId!=='theme'||twDocs().length)return html;const root=document.createElement('div');root.innerHTML=html;const empty=root.querySelector('.ef-empty');if(empty)empty.innerHTML='<span class="ef-empty-symbol">'+I('layers')+'</span><h2>把同类事项放在一起看</h2><p>汇总合同、会议纪要、批复等资料中的共同事项，便于对照审计资料。</p><p class="th-preview-example">例如：预算安排、采购付款、合同履约。</p><p class="tw-note">先在左侧添加资料，再按需要调整右侧归纳要求。</p>';return root.innerHTML;};
awPromptModal=function(p){const html=thBase.awPromptModal(p);if(state.toolId!=='theme')return html;const root=document.createElement('div');root.innerHTML=html;root.querySelector('.modal')?.classList.add('th-prompt-dialog');const locked=!!currentTask();root.querySelector('.modalhead h2').textContent=locked?'本次归纳要求':'调整归纳要求';root.querySelector('.modalhead p').textContent='分别说明要摘录什么、如何汇总；两项要求会一并用于本次归纳。';root.querySelectorAll('.field>span').forEach(n=>{if(n.textContent==='提示词模板')n.textContent='要求模板';});root.querySelectorAll('optgroup').forEach(n=>n.label=n.label.replace('系统提示词','系统预设').replace('个人提示词','个人预设'));root.querySelectorAll('option').forEach(n=>n.textContent=n.textContent.replace('基础信息提取','资料要点摘录'));const save=root.querySelector('[data-action=aw-store-prompt]');if(save)save.textContent='另存为个人要求';root.querySelector('.aw-prompt-bottom>span').textContent='保存要求后，点击页面上的“开始归纳”执行。';return root.innerHTML;};
function thReadable(task){const v=av('theme');return (task.result||[]).filter(r=>{const d=file(r.doc);return d&&!d.deleted&&auditFileAccess(d).read&&(v.resultScope==='all'||r.doc===v.resultScope)&&(!v.resultFolder||d.space===v.resultFolder.space&&underFolder(d.folder,v.resultFolder.path));});}
function thRows(task){const v=av('theme'),q=v.resultQuery.trim().toLowerCase();return thReadable(task).filter(r=>(!v.themeTopic||thTopicName(r)===v.themeTopic)&&[r.topic,r.title,r.unit,r.excerpt,r.date,r.amount,file(r.doc)?.name].join(' ').toLowerCase().includes(q));}
awRows=function(task){return task.toolId==='theme'?thRows(task):thBase.awRows(task);};
function thSummaryText(task){const values=[task.themeSummaryText,task.topic_summary,task.themeSummary];for(let value of values){for(let i=0;i<6;i++){if(typeof value==='string'){if(!value.trim())break;try{const parsed=JSON.parse(value);if(parsed&&typeof parsed==='object'){value=parsed;continue;}}catch{}return value.trim().replace(/^```(?:markdown|md)?\s*\n([\s\S]*?)\n```\s*$/,'$1');}if(!value||typeof value!=='object')break;value=value.data?.outputs||value.outputs||value.text||value.answer||value.summary||value.result||value.content;} }return '';}
function thSummaryAccess(task,download=false){return (task.ids||[]).every(id=>{const d=file(id);return d&&!d.deleted&&auditFileAccess(d).read&&(!download||auditFileAccess(d).download);});}
function thTopicName(row){return String(row.topic||'未归类事项');}
function thPager(page,pages,count,unit){return '<footer class="th-pagination"><span>共 <strong>'+count+'</strong> '+unit+'</span><div>'+B('上一页','th-page','ghost sm','data-step="-1" '+(page<=1?'disabled':''))+'<span>'+page+' / '+pages+'</span>'+B('下一页','th-page','ghost sm','data-step="1" '+(page>=pages?'disabled':''))+'</div></footer>';}
function thControls(task,native){const v=av('theme'),topics=[...new Set(thReadable(task).map(thTopicName))],active=v.resultQuery||v.themeTopic||v.resultScope!=='all';return '<div class="th-result-tools"><div class="search">'+I('search','icon-sm')+'<input id="aw-result-query" aria-label="搜索归纳结果" placeholder="'+(native?'查找依据资料':'查找主题、事项或资料')+'" data-aw-input="result" value="'+E(v.resultQuery)+'"></div><select data-th-change="topic" aria-label="筛选主题"><option value="">全部主题</option>'+topics.map(name=>'<option value="'+E(name)+'" '+(v.themeTopic===name?'selected':'')+'>'+E(name)+'</option>').join('')+'</select><select data-th-change="scope" aria-label="结果文件范围"><option value="all">全部分析资料</option>'+(task.successIds||task.ids).filter(id=>file(id)&&!file(id).deleted&&auditFileAccess(file(id)).read).map(id=>'<option value="'+E(id)+'" '+(v.resultScope===id?'selected':'')+'>'+E(file(id).name)+'</option>').join('')+'</select>'+B('清除筛选','aw-clear','ghost sm',active?'':'disabled')+'</div>';}
function thBaseTable(task,rows){const v=av('theme'),pages=Math.max(1,Math.ceil(rows.length/20));v.resultPage=Math.max(1,Math.min(v.resultPage,pages));return '<div class="aw-table-scroll th-base-scroll"><table class="table aw-table th-base-table"><thead><tr><th>资料名称</th><th>资料要点</th><th>涉及单位</th><th>金额与单位</th><th>日期</th><th>原文</th></tr></thead><tbody>'+pageItems(rows,v.resultPage,20).map(r=>'<tr><td><strong>'+E(file(r.doc)?.name||r.title)+'</strong><small>'+E(thTopicName(r))+'</small></td><td><p title="'+E(r.excerpt||'未提取到')+'">'+E(r.excerpt||'未提取到')+'</p></td><td>'+E(r.unit||'未提取到')+'</td><td>'+E(r.amount||'未提取到')+'</td><td>'+E(r.date||'未提取到')+'</td><td>'+awReviewLink(task,r)+'</td></tr>').join('')+'</tbody></table>'+(!rows.length?awEmpty():'')+'</div>'+thPager(v.resultPage,pages,rows.length,'条要点');}
function thTopicCards(task,rows){const v=av('theme'),topics=[...new Set(rows.map(thTopicName))],pages=Math.max(1,Math.ceil(topics.length/8));v.resultPage=Math.max(1,Math.min(v.resultPage,pages));v.themeLimits??={};return '<div class="aw-results-scroll th-topic-scroll">'+pageItems(topics,v.resultPage,8).map((name,i)=>{const entries=rows.filter(r=>thTopicName(r)===name),limit=v.themeLimits[name]||3,shown=entries.slice(0,limit);return '<article class="th-topic-card"><header><h3><span>'+((v.resultPage-1)*8+i+1)+'</span>'+E(name)+'</h3><span>涉及 <strong>'+new Set(entries.map(r=>r.doc)).size+'</strong> 份资料</span></header><div class="th-topic-entries">'+shown.map(r=>'<section><p>'+E(r.excerpt||'当前未返回可展示的事项要点，请核对原文。')+'</p><div><span title="'+E(file(r.doc)?.name||r.title)+'">来源：'+E(file(r.doc)?.name||r.title)+'</span>'+awReviewLink(task,r)+'</div></section>').join('')+'</div>'+(entries.length>limit?B('查看其余 '+(entries.length-limit)+' 条要点','th-more-topic','ghost sm','data-topic="'+E(name)+'"'):'')+'</article>';}).join('')+(!topics.length?awEmpty():'')+'</div>'+thPager(v.resultPage,pages,topics.length,'个主题');}
awTheme=function(task){const v=av('theme');if(v.themeResultId!==task.id){v.themeResultId=task.id;v.themeTopic='';v.themeLimits={};v.resultPage=1;}const rows=thRows(task),all=thReadable(task),base=v.tab==='base',native=thSummaryText(task),ready=!task.summaryFailed&&!task.summaryGenerating,topics=[...new Set(rows.map(thTopicName))],count=new Set((native&&!base?(task.result||[]).filter(r=>file(r.doc)&&!file(r.doc).deleted&&auditFileAccess(file(r.doc)).read):all).map(r=>r.doc)).size;return '<header class="th-result-heading"><h2 title="'+E(task.name)+'">'+E(task.name||'主题归纳结果')+'</h2><span>已摘录 <strong>'+count+'</strong> 份资料'+(ready&&!native?' · '+topics.length+' 个主题':'')+'</span></header><div class="th-result-tabs" role="tablist" aria-label="主题归纳结果"><button data-action="aw-view" data-id="main" aria-selected="'+!base+'" class="'+(!base?'active':'')+'">主题汇总</button><button data-action="aw-view" data-id="base" aria-selected="'+base+'" class="'+(base?'active':'')+'">资料要点</button><span>'+(base?'逐份核对资料内容与原文':'按主题查看同类事项')+'</span></div>'+(base||ready&&!native?thControls(task,false):'')+(base?((task.summaryFailed||task.summaryGenerating)?'<div class="th-stage-note">'+(task.summaryGenerating?'正在汇总主题，资料要点可继续查看。':'主题汇总未完成，已摘录的资料要点保留。')+(!task.summaryGenerating?B('重试主题汇总','aw-summary-retry','ghost sm'):'')+'</div>':'')+thBaseTable(task,rows):!ready?'<div class="aw-stage-loading th-stage-empty"><h2>'+(task.summaryGenerating?'正在汇总同类事项':'资料已摘录，主题汇总未完成')+'</h2><p>'+(task.summaryGenerating?'使用本次已摘录要点，完成后在此查看主题汇总。':'可先查看资料要点，或重试主题汇总。')+'</p><div>'+B('查看资料要点','aw-view','sm','data-id="base"')+(!task.summaryGenerating?B('重试主题汇总','aw-summary-retry','primary'):'')+'</div></div>':native?(thSummaryAccess(task)?'<div class="th-native-summary aw-results-scroll"><article class="preview-parsed-markdown">'+previewMarkdown(native)+'</article></div>':'<div class="aw-stage-loading"><h2>部分来源资料当前不可查看</h2><p>完整主题汇总暂不可用，可查看有权限的资料要点。</p>'+B('查看资料要点','aw-view','sm','data-id="base"')+'</div>'):thTopicCards(task,rows))+'<div class="th-result-note">'+(native&&!base?'主题汇总覆盖本次全部资料；按文件核对请切换“资料要点”。':'主题汇总基于本次资料，审计认定仍需核对原文及业务凭证。')+'</div>';};
awProgress=function(task){const html=thBase.awProgress(task);return task.toolId==='theme'?html.replaceAll('提取基础信息','摘录资料要点').replaceAll('归纳主题','汇总同类事项'):html;};
awReviewHTML=function(task,p){if(task.toolId!=='theme')return thBase.awReviewHTML(task,p);const r=task.result?.[p.index]||task.result?.find(r=>r.doc===p.id);if(!r)return '<p>当前没有对应的资料要点。</p>';return '<div class="aw-review-heading"><h2>'+E(thTopicName(r))+'</h2><span>本次归纳使用的资料要点</span></div><div class="aw-review-body"><h3>资料要点</h3><blockquote>'+E(r.excerpt||'未提取到')+'</blockquote><dl><dt>涉及单位</dt><dd>'+E(r.unit||'未提取到')+'</dd><dt>金额与单位</dt><dd>'+E(r.amount||'未提取到')+'</dd><dt>日期</dt><dd>'+E(r.date||'未提取到')+'</dd></dl>'+B('在解析内容中定位','aw-locate','soft sm','data-term="'+E(r.excerpt||'')+'"')+'</div>';};
modalContent=function(){let html=thBase.modalContent();if(state.toolId!=='theme')return html;const root=document.createElement('div');root.innerHTML=html;if(modal==='aw-submit'){root.querySelector('.modalhead h2').textContent='开始主题归纳';root.querySelector('.modalhead p').textContent='确认本次资料和任务名称，自动完成资料摘录与主题汇总。';root.querySelector('.ew-submit-summary>span:nth-child(2)')?.remove();root.querySelector('[data-action=aw-submit-confirm]').textContent='确认归纳';root.querySelector('.modalbody>.hint')?.remove();}return root.innerHTML;};
handleAction=function(action,el){if(state.toolId==='theme'){const v=av('theme');if(action==='aw-view')v.resultPage=1;if(action==='aw-clear'){v.themeTopic='';v.resultPage=1;}if(action==='th-page'){v.resultPage+=+el.dataset.step;render();return;}if(action==='th-more-topic'){v.themeLimits??={};v.themeLimits[el.dataset.topic]=(v.themeLimits[el.dataset.topic]||3)+20;const scroll=document.querySelector('.th-topic-scroll')?.scrollTop||0;render();const body=document.querySelector('.th-topic-scroll');if(body)body.scrollTop=scroll;return;}}return thBase.handleAction(action,el);};
window.addEventListener('change',e=>{const key=e.target.dataset.thChange;if(!key||state.toolId!=='theme'||!currentTask())return;e.stopImmediatePropagation();const v=av('theme');if(key==='topic')v.themeTopic=e.target.value;if(key==='scope')v.resultScope=e.target.value;v.resultPage=1;queueMicrotask(()=>render());},true);
tcOutput=function(task){const output=thBase.tcOutput(task);return task.toolId==='theme'?{text:output.text.replaceAll('基础信息','资料要点'),hint:output.hint.replaceAll('基础信息','资料要点')}:output;};
awOutputRows=function(task,rows){if(task.toolId!=='theme')return thBase.awOutputRows(task,rows);return [['主题','资料名称','资料要点','涉及单位','金额与单位','日期','资料位置'],...rows.map(r=>[thTopicName(r),file(r.doc)?.name||r.title,r.excerpt||'未提取到',r.unit||'未提取到',r.amount||'未提取到',r.date||'未提取到',file(r.doc)?ewPath(file(r.doc)):'原资料已移除'])];};
function thExportSummary(task,rows,scope){if(scope!=='all'||task.summaryFailed||task.summaryGenerating||!thSummaryAccess(task,true))return '';const native=thSummaryText(task);if(native)return native;return [...new Set(rows.map(thTopicName))].map(name=>'### '+name+'\n\n'+rows.filter(r=>thTopicName(r)===name).map(r=>'- '+(r.excerpt||'未提取到')+'（来源：'+(file(r.doc)?.name||r.title)+'）').join('\n')).join('\n\n');}
awDoExport=function(){const task=currentTask();if(task?.toolId!=='theme')return thBase.awDoExport();const scope=document.getElementById('aw-export-scope')?.value||'all',format=document.getElementById('aw-export-format').value,rows=awExportableRows(task,scope);if(!rows.length)return toast('当前范围没有可导出的资料要点，或资料权限已变化。');const matrix=awOutputRows(task,rows),summary=thExportSummary(task,rows,scope),name=(task.name||'主题归纳').replace(/[\\/:*?"<>|]/g,'-'),snapshot=awExecutionSnapshot(task);if(format==='xlsx'){const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(matrix),'资料要点');if(summary){const chunks=[['段落','主题汇总']];for(let i=0;i<summary.length;i+=30000)chunks.push([i/30000+1,summary.slice(i,i+30000)]);XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(chunks),'主题汇总');}const config=[['任务名称',task.name],['任务备注',task.notes||''],['导出范围',scope==='all'?'本次全部可下载结果':scope==='filtered'?'当前筛选的资料要点':file(scope)?.name||scope]],text=JSON.stringify(snapshot);for(let i=0;i<text.length;i+=30000)config.push(['本次要求 '+(i/30000+1),text.slice(i,i+30000)]);XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(config),'本次要求');XLSX.writeFile(wb,name+'.xlsx');}else if(format==='csv')download(name+'-资料要点.csv','\uFEFF'+matrix.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');else if(format==='markdown')download(name+'.md','# '+task.name+'\n\n'+(summary?'## 主题汇总\n\n'+summary+'\n\n':'')+'## 资料要点\n\n'+awMarkdownTable(matrix),'text/markdown;charset=utf-8');else download(name+'.json',JSON.stringify({task:task.name,notes:task.notes,config:task.config,exec_config:snapshot,scope,theme_summary:summary||null,results:rows.map(r=>({...r,source_file:file(r.doc)?.name,source_path:file(r.doc)?ewPath(file(r.doc)):null}))},null,2),'application/json;charset=utf-8');closeModal();};
const thExportModalBase=modalContent;
modalContent=function(){const html=thExportModalBase();if(state.toolId!=='theme'||modal!=='aw-export')return html;const root=document.createElement('div');root.innerHTML=html;root.querySelector('.modalhead h2').textContent='导出主题归纳结果';root.querySelector('.modalhead p').textContent='保存主题汇总及资料要点，保留来源和本次要求。';const select=root.querySelector('#aw-export-format');select.querySelectorAll('option').forEach(n=>n.textContent=({xlsx:'Excel · 资料要点、主题汇总与本次要求',csv:'CSV · 资料要点表',markdown:'Markdown · 主题汇总与资料要点',json:'JSON · 完整结果与本次要求'})[n.value]||n.textContent);root.querySelector('.modalbody>.hint')?.remove();const task=currentTask(),unavailable=task.summaryFailed||task.summaryGenerating||!thSummaryAccess(task,true);root.querySelector('.modalbody').insertAdjacentHTML('beforeend','<p class="th-export-note">'+(unavailable?'主题汇总尚不可导出，本次可保存有权限的资料要点。':'主题汇总随“本次全部结果”导出；选择当前筛选或单份资料时，仅导出对应要点。CSV仅保存资料要点。')+'</p>');return root.innerHTML;};
render();
